<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{useClassicGame}from'../composables/useClassicGame';import{useI18n,locale}from'../i18n';import{player}from'../stores';import{shareText}from'../utils';const g=useClassicGame(),{t}=useI18n(),router=useRouter(),menu=ref(false);onMounted(g.begin);function toggleMenu(){menu.value=!menu.value;g.pause()}async function share(){await shareText(`FLAG STREAK 🌍\n🔥 ${g.score.value} ${t.value('flags')}\n🏆 ${t.value('record')}: ${player.best}\n`)}function quit(){if(g.status.value==='paused'||confirm(t.value('quit')))router.push('/home')}</script>
<template><section class="screen game" :class="g.status.value"><div v-if="g.status.value==='countdown'" class="countdown">{{g.countdown.value||'GO!'}}</div><template v-else-if="g.status.value!=='gameOver'"><header class="game-head"><button class="icon-btn home-btn" @click="quit" :aria-label="t('home')">⌂</button><strong>🔥 {{g.score.value}}</strong><button class="icon-btn pause-btn" @click="toggleMenu" :aria-label="t('pause')">⏸</button><strong>🏆 {{player.best}}</strong></header><div class="timer" :class="{urgent:g.time.value<=3}"><span :style="{width:g.progress.value+'%'}"></span><b>{{g.time.value.toString().padStart(2,'0')}}</b></div><div v-if="g.question.value" class="question"><div class="flag"><img :src="g.question.value.country.flagAsset" :alt="t('which')"></div><h2>{{t('which')}}</h2><div class="answers"><button v-for="a in g.question.value.answers" :key="a.code" :disabled="g.status.value!=='playing'" :class="{correct:g.status.value!=='playing'&&a.code===g.question.value.country.code,wrong:g.selected.value===a.code&&a.code!==g.question.value.country.code}" @click="g.answer(a)">{{a.names[locale]}}</button></div></div><div v-if="menu" class="modal"><div><h2>⏸ {{t('pause')}}</h2><button class="primary" @click="toggleMenu">{{t('resume')}}</button><button @click="router.push('/home')">⌂ {{t('home')}}</button></div></div></template><div v-else class="result"><div class="burst">{{g.isRecord.value?'🏆':'💥'}}</div><h1>{{g.isRecord.value?t('newRecord'):t('gameOver')}}</h1><p>{{t('answerWas')}}</p><img v-if="g.question.value" class="result-flag" :src="g.question.value.country.flagAsset" :alt="g.question.value.country.names[locale]"><strong>{{g.question.value?.country.names[locale]}}</strong><div class="result-stats"><span>{{t('score')}}<b>{{g.score.value}}</b></span><span>{{t('record')}}<b>{{player.best}}</b></span></div><button class="primary" @click="g.begin">{{t('replay')}}</button><button @click="router.push('/home')">⌂ {{t('home')}}</button><button class="text-btn" @click="share">↗ {{t('share')}}</button></div></section></template>
